 * Parses election text into a list of candidate names and a list of ballots.
 * Throws an Error whose message is the exact text to report (without the
 * `error: ` prefix) when the input violates the election format.
 */

const NAME = /^[A-Za-z0-9_-]+$/

function fail (line, message) {
  const err = new Error(line === undefined ? message : `line ${line}: ${message}`)
  throw err
}

function splitWords (line) {
  return line.split(/\s+/).filter((word) => word.length > 0)
}

export function parseElection (input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = splitWords(trimmed)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const names = words.slice(1)
      if (names.length === 0) {
        fail(lineNumber, 'expected candidates <name>...')
      }
      for (const name of names) {
        if (!NAME.test(name)) {
          fail(lineNumber, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          fail(lineNumber, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const rest = words.slice(1)
      if (rest.length < 2) {
        fail(lineNumber, 'expected ballot <count> <candidate>...')
      }
      const countText = rest[0]
      if (!/^[1-9][0-9]*$/.test(countText)) {
        fail(lineNumber, 'count must be a positive integer')
      }
      const count = Number(countText)
      const names = rest.slice(1)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(lineNumber, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNumber, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    fail(undefined, 'no candidates')
  }

  return { candidates, ballots }
}
"}

