{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-vuqbBw/src/count.js","content":"/**
 * Runs the instant-runoff count for a parsed election and returns the round
 * by round results plus the eventual winner, if any.
 */

function tieBreakEliminate (group, history, roundCount) {
  let pool = group.slice()
  while (pool.length > 1) {
    let narrowed = false
    for (let round = 0; round < roundCount; round++) {
      const counts = pool.map((name) => history.get(name)[round])
      const min = Math.min(...counts)
      if (!counts.every((value) => value === min)) {
        pool = pool.filter((name) => history.get(name)[round] === min)
        narrowed = true
        break
      }
    }
    if (!narrowed) break
  }
  if (pool.length === 1) return pool[0]
  return pool.reduce((worst, name) => (name > worst ? name : worst))
}

export function runElection ({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((name) => [name, []]))
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    for (const name of continuing) history.get(name).push(votes.get(name))

    const activeTotal = [...votes.values()].reduce((sum, v) => sum + v, 0)
    const roundNumber = rounds.length + 1

    let eliminated = null
    if (activeTotal > 0) {
      for (const [name, count] of votes) {
        if (count * 2 > activeTotal) {
          winner = name
          break
        }
      }
    }

    if (winner === null && activeTotal > 0) {
      let min = Infinity
      for (const count of votes.values()) min = Math.min(min, count)
      const tied = [...votes.keys()].filter((name) => votes.get(name) === min)
      eliminated = tieBreakEliminate(tied, history, roundNumber)
    }

    rounds.push({ votes, exhausted, eliminated })

    if (winner !== null || activeTotal === 0) break

    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
"}

