/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection } from './parse.js'
import { runElection } from './count.js'

function formatRound (roundNumber, votes) {
  const entries = [...votes.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : 1
  })
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

function main () {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  let input = ''
  try {
    input = require('node:fs').readFileSync(0, 'utf8')
  } catch (err) {
    input = ''
  }

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }

  const { rounds, winner } = runElection(election)

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const header = formatRound(index + 1, round.votes)
      lines.push(`${header} exhausted=${round.exhausted}`)
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }
  lines.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

